size, sword = map(int, input().split()); sword -= 1

vector = [i for i in range(1, size +1)]

def printv():
    print("[ ", end="")
    for i in range(size):
        print(vector[i] if vector[i] != 0 else "", end="")
        if i == sword:
            print(">", end="")
        print(" ", end="")
    print("]")

while vector.count(0) != len(vector):
    printv()
    dead = -1
    for i in range(sword+1, size):
        if(vector[i] != 0):
            vector[i] = 0
            dead = i
            break
    for i in range(dead, size):
        if(vector[i] != 0):
            sword = i
            break
